let selected='All';const search=document.querySelector('#search');function render(){const q=search.value.trim().toLowerCase();const items=sagas.filter(s=>(selected==='All'||s.world===selected)&&[s.world,s.title,...s.arcs].join(' ').toLowerCase().includes(q));document.querySelector('#catalog').replaceChildren(...items.map(s=>{const el=document.createElement('article');el.className='saga';el.innerHTML=`<span class="eyebrow">${s.world.toUpperCase()}</span><h3>${s.title}</h3><p>${s.count}</p><ul>${s.arcs.map(a=>`<li>${a}</li>`).join('')}</ul><div class="availability">${s.available}</div><details><summary>About this edition</summary><p>${s.note}</p></details>`;return el}));document.querySelector('#result-count').textContent=`${items.length} ${items.length===1?'saga':'sagas'} / ${items.reduce((n,s)=>n+s.arcs.length,0)} book arcs`;document.querySelector('#empty').hidden=items.length>0;document.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===selected;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.filter;render()}));document.querySelectorAll('[data-select]').forEach(a=>a.addEventListener('click',()=>{selected=a.dataset.select;search.value='';render()}));search.addEventListener('input',render);render();
